    def offer_packages(self, case, threads, sid, research):
        """Create the current BATNA-safe package set without drafting email prose."""
        events = threads[sid]
        if moves_left(case, events) <= 0 or latest(events).get("status") in {"final_offer", "agreed"}:
            return []
        state = self._state(case, sid, events, research)
        standard = state["standard"]
        cap = self.batna(case, {other: messages for other, messages in threads.items() if other != sid}, sid, research)[0]
        history = [message for message in events if message.get("from") == "buyer" and message.get("term_sheets")]
        offer_cap = self._earned_cap(case, events, history, standard, sid, cap, research)
        if history:
            previous = history[-1]["term_sheets"][0]["terms"].get("unit_price", state["target"])
            remaining = max(1, min(5, case.get("round_limit", 10) - 1 - state["turn"]))
            planned_price = float(previous) + (state["target"] - float(previous)) / remaining
            planned_price = min(state["target"], planned_price)
        else:
            planned_price = state["target"] * 0.96
        template = state["terms"] or {}
        primary = self._optimize_terms(
            case, complete_offer(case, {**template, "unit_price": max(0.01, planned_price)}),
            standard, sid, research,
        )
        return self._packages(case, primary, standard, sid, offer_cap, research)

    def decide(self, case, threads, research, writer):
        live = live_threads(threads)
        if not live:
            raise ValueError("cannot decide after all supplier threads have ended")
        states = {sid: self._state(case, sid, threads[sid], research) for sid in live}
        caps = {
            sid: self.batna(case, {other: events for other, events in threads.items() if other != sid}, sid, research)[0]
            for sid in live
        }

        ready = []
        for sid, state in states.items():
            if (state["valid"] and state["sheet_id"] and state["cost"] <= caps[sid] + 0.01
                    and state["cost"] <= self.acceptance_threshold(case, threads[sid], state, caps[sid]) + 0.01):
                ready.append((state["cost"], sid, state["sheet_id"]))
        if ready:
            _, sid, offer_id = min(ready)
            return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": offer_id}}}

        writable = [sid for sid in live if moves_left(case, threads[sid]) > 0
                    and states[sid]["status"] not in {"final_offer", "agreed"}]
        if not writable:
            return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}

        # Work the best priced supplier first, then try the remaining open suppliers if its
        # discrete terms cannot produce any BATNA-safe offer.
        quoted = [sid for sid in writable if states[sid]["valid"]]
        offer_order = sorted(quoted, key=lambda item: (states[item]["cost"], item))
        offer_order += sorted(
            (sid for sid in writable if sid not in quoted),
            key=lambda item: (states[item]["target_cost"], item),
        )
        sid, packages = None, []
        for candidate_sid in offer_order:
            candidate_packages = self.offer_packages(case, threads, candidate_sid, research)
            if candidate_packages:
                sid, packages = candidate_sid, candidate_packages
                break
        if not packages:
            return {"supplier_id": live[0], "message": {"action": {"type": "walk_away"}}}
        evidence_line, refs = self.researcher.opening_evidence(case, research)
        trade_descriptions = []
        for package in packages[1:]:
            if package.get("payment_days", math.inf) < packages[0].get("payment_days", math.inf):
                trade_descriptions.append("earlier payment")
            if package.get("contract_months", 0) > packages[0].get("contract_months", 0):
                trade_descriptions.append("a longer commitment")
        draft = writer.draft(case, latest(threads[sid]), evidence_line, trade_descriptions)
        # Verified evidence is inserted by code; the language model is not allowed to alter it.
        body = evidence_line + "\n\n" + draft
        return {
            "supplier_id": sid,
            "message": {
                "subject": f"Re: {case['title']}"[:300],
                "body": body[:8000],
                "term_sheets": [{"terms": package} for package in packages],
                "refs": refs[:20],
            },
        }
        po_rows.sort(key=lambda row: row.get("date", ""), reverse=True)
        quotes.sort(key=lambda row: row.get("date", ""), reverse=True)
        costs = [row for row in other["costs"] if row.get("price") is not None]
        costs.sort(key=lambda row: (row.get("supplier_id") in suppliers, row.get("date", "")), reverse=True)
        moves = self._market_moves(case.get("parts", []))

        refs = []
        for row in po_rows + quotes + costs + list(latest_cards.values()):
            ref = row.get("id")
            if self.valid_ref(case, ref) and ref not in refs:
                refs.append(ref)
        for move in moves:
            for ref in (move["start_ref"], move["end_ref"]):
                if self.valid_ref(case, ref) and ref not in refs:
                    refs.append(ref)
        return {
            "units": units,
            "purchase_history": po_rows,
            "quotes": quotes,
            "should_cost": costs,
            "scorecards": latest_cards,
            "market_moves": moves,
            "refs": refs[:20],
        }

    @staticmethod
    def weighted_market_change(research):
        moves = [move for move in research["market_moves"] if move["weight"] > 0]
        weight = sum(move["weight"] for move in moves)
        if not weight:
            return 0.0
        change = sum(move["weight"] * move["change_pct"] for move in moves)
        if weight > 1:
            change /= weight
        return max(-12.0, min(12.0, change))

    def opening_evidence(self, case, research):
        """A short verifiable claim; keep only IDs the case/package can resolve."""
        # A series change is the clearest argument when both endpoints are available.
        for move in research["market_moves"]:
            if self.valid_ref(case, move["start_ref"]) and self.valid_ref(case, move["end_ref"]):
                sentence = (
                    f"{move['series']} moved {move['change_pct']:+.1f}% from {move['start_month']} "
                    f"to {move['end_month']} ({move['start_ref']}, {move['end_ref']})."
                )
                return sentence, [move["start_ref"], move["end_ref"]]

        by_part = {}
        for row in research["purchase_history"]:
            ref = row.get("id")
            if row.get("part_id") and row.get("price") is not None and self.valid_ref(case, ref):
                by_part.setdefault(row["part_id"], []).append(row)
        for part, rows in by_part.items():
            if len(rows) >= 2:
                first, second = rows[:2]
                sentence = (
                    f"Our matching records for {part} list EUR {float(first['price']):.2f} in {first['id']} "
                    f"and EUR {float(second['price']):.2f} in {second['id']}."
                )
                return sentence, [first["id"], second["id"]]
        return "Thank you for your offer. We have reviewed it against the case requirements.", []
